// Makes a failed run visible: workflow name, execution id and the error message.
const e = $input.first().json;
const line = '[error-handler] workflow "' + (e.workflow && e.workflow.name) + '" failed, execution ' + (e.execution && e.execution.id) + ': ' + (e.execution && e.execution.error && e.execution.error.message);
console.log(line);
return [{ json: { message: line } }];
